   Elysia 大学申请攻略 - 样式表
   风格：柔和渐变 + 轻二次元 + 卡片式布局
   移动端优先，类微信小程序UI
   ======================================== */

/* Tailwind CSS CDN */
@import url('https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css');

/* ==================== CSS 变量 ==================== */
:root {
    --primary: #8B5CF6;
    --primary-light: #A78BFA;
    --primary-lighter: #C4B5FD;
    --bg-primary: #FAF5FF;
    --bg-white: #FFFFFF;
    --bg-light: #F5F3FF;
    --text-primary: #1E1B4B;
    --text-secondary: #6B7280;
    --text-muted: #9CA3AF;
    --danger: #EF4444;
    --success: #10B981;
    --warning: #F59E0B;
    --info: #3B82F6;
    --border: #E5E7EB;
    --shadow: 0 2px 12px rgba(139,92,246,0.08);
    --shadow-lg: 0 8px 32px rgba(139,92,246,0.12);
    --radius: 16px;
    --radius-sm: 10px;
    --radius-xs: 8px;
    --nav-height: 64px;
    --header-height: 56px;
    --gradient-1: linear-gradient(135deg, #8B5CF6, #6366F1);
    --gradient-2: linear-gradient(135deg, #A78BFA, #EC4899);
    --gradient-3: linear-gradient(135deg, #3B82F6, #8B5CF6);
    --gradient-4: linear-gradient(135deg, #10B981, #3B82F6);
    --gradient-card: linear-gradient(135deg, #FAF5FF, #EDE9FE);
}

/* ==================== 基础重置 ==================== */
* { margin: 0; padding: 0; box-sizing: border-box; }

html {
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Segoe UI', 'Helvetica Neue', sans-serif;
    background: #F3F4F6;
    color: var(--text-primary);
    line-height: 1.6;
    overflow-x: hidden;
    display: flex;
    justify-content: center;
    min-height: 100vh;
}

/* ==================== 手机容器 ==================== */
#app-container {
    width: 100%;
    max-width: 480px;
    min-height: 100vh;
    background: var(--bg-primary);
    position: relative;
    overflow-x: hidden;
    padding-bottom: calc(var(--nav-height) + 16px);
}

@media (min-width: 769px) {
    #app-container {
        box-shadow: 0 0 60px rgba(139,92,246,0.15);
        margin: 0 auto;
        min-height: 100vh;
        border-left: 1px solid var(--border);
        border-right: 1px solid var(--border);
    }
}

/* ==================== 页面容器 ==================== */
.page {
    display: none;
    padding: 16px;
    padding-top: calc(var(--header-height) + 16px);
    animation: fadeInUp 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.page.active { display: block; }

@keyframes fadeInUp {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: translateY(0); }
}

@keyframes scaleIn {
    from { opacity: 0; transform: scale(0.92); }
    to { opacity: 1; transform: scale(1); }
}

@keyframes slideUp {
    from { opacity: 0; transform: translateY(30px); }
    to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
    0%, 100% { box-shadow: 0 0 0 0 rgba(239,68,68,0.4); }
    50% { box-shadow: 0 0 0 8px rgba(239,68,68,0); }
}

@keyframes float {
    0%, 100% { transform: translateY(0px); }
    50% { transform: translateY(-6px); }
}

@keyframes shimmer {
    0% { background-position: -200% 0; }
    100% { background-position: 200% 0; }
}

/* ==================== 顶部导航栏 ==================== */
.top-header {
    position: fixed;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 100%;
    max-width: 480px;
    height: var(--header-height);
    background: rgba(255,255,255,0.85);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 16px;
    z-index: 100;
    border-bottom: 1px solid transparent;
    transition: border-color 0.3s, box-shadow 0.3s;
}

.top-header.scrolled {
    border-bottom-color: var(--border);
    box-shadow: 0 1px 8px rgba(0,0,0,0.04);
}

.header-title {
    font-size: 17px;
    font-weight: 700;
    background: var(--gradient-1);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.header-icon {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: var(--gradient-2);
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 18px;
    cursor: pointer;
    transition: transform 0.2s;
}

.header-icon:active { transform: scale(0.9); }

/* ==================== 底部导航 ==================== */
.bottom-nav {
    position: fixed;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 100%;
    max-width: 480px;
    height: var(--nav-height);
    background: rgba(255,255,255,0.95);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    display: flex;
    align-items: center;
    justify-content: space-around;
    border-top: 1px solid var(--border);
    z-index: 100;
    padding-bottom: env(safe-area-inset-bottom, 0);
}

.nav-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    cursor: pointer;
    padding: 6px 10px;
    border-radius: var(--radius-xs);
    transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    -webkit-tap-highlight-color: transparent;
    user-select: none;
}

.nav-item .nav-icon {
    font-size: 22px;
    transition: transform 0.25s;
}

.nav-item .nav-label {
    font-size: 11px;
    color: var(--text-muted);
    font-weight: 500;
    transition: color 0.25s;
}

.nav-item.active .nav-icon {
    transform: translateY(-2px);
}

.nav-item.active .nav-label {
    color: var(--primary);
    font-weight: 600;
}

.nav-item:active .nav-icon { transform: scale(1.15); }

/* ==================== 卡片系统 ==================== */
.card {
    background: var(--bg-white);
    border-radius: var(--radius);
    padding: 16px;
    margin-bottom: 14px;
    box-shadow: var(--shadow);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    border: 1px solid transparent;
}

.card:active {
    transform: scale(0.97);
    box-shadow: var(--shadow-lg);
}

.card-gradient {
    background: var(--gradient-card);
    border: 1px solid rgba(139,92,246,0.08);
}

.card-highlight {
    border: 1.5px solid var(--primary-light);
    background: linear-gradient(135deg, #FFFFFF, #FAF5FF);
}

.card-danger {
    border-left: 4px solid var(--danger);
    animation: pulse 2s infinite;
}

/* ==================== 首页仪表盘 ==================== */
.profile-card {
    background: var(--bg-white);
    border-radius: var(--radius);
    padding: 20px;
    margin-bottom: 14px;
    position: relative;
    overflow: hidden;
    box-shadow: var(--shadow);
}

.profile-card::before {
    content: '';
    position: absolute;
    top: -40px;
    right: -40px;
    width: 140px;
    height: 140px;
    background: var(--gradient-2);
    border-radius: 50%;
    opacity: 0.08;
}

.profile-header {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 14px;
}

.profile-avatar {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    background: var(--gradient-2);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 28px;
    color: white;
    flex-shrink: 0;
    position: relative;
    z-index: 1;
}

.profile-name {
    font-size: 20px;
    font-weight: 700;
    color: var(--text-primary);
}

.profile-subtitle {
    font-size: 12px;
    color: var(--text-secondary);
    margin-top: 2px;
}

.profile-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.tag {
    padding: 4px 10px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 500;
    white-space: nowrap;
}

.tag-accent { background: #EDE9FE; color: var(--primary); }
.tag-blue { background: #DBEAFE; color: var(--info); }
.tag-green { background: #D1FAE5; color: var(--success); }
.tag-yellow { background: #FEF3C7; color: #D97706; }
.tag-red { background: #FEE2E2; color: var(--danger); }

.profile-stats {
    display: flex;
    gap: 8px;
    margin-top: 12px;
}

.stat-item {
    flex: 1;
    background: #F5F3FF;
    border-radius: var(--radius-xs);
    padding: 10px;
    text-align: center;
}

.stat-value { font-size: 18px; font-weight: 700; color: var(--primary); }
.stat-label { font-size: 11px; color: var(--text-secondary); margin-top: 2px; }

/* IELTS差距卡片 */
.ielts-card {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 16px;
    background: #FEF2F2;
    border: 1.5px solid #FECACA;
    border-radius: var(--radius);
    margin-bottom: 14px;
}

.ielts-icon {
    font-size: 36px;
    flex-shrink: 0;
    animation: float 3s ease-in-out infinite;
}

.ielts-info { flex: 1; }

.ielts-title {
    font-size: 14px;
    font-weight: 700;
    color: var(--danger);
}

.ielts-desc { font-size: 12px; color: #991B1B; margin-top: 4px; }

.ielts-arrow {
    font-size: 24px;
    color: var(--danger);
    animation: float 2s ease-in-out infinite;
}

/* 统计卡片 */
.stats-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    margin-bottom: 14px;
}

.stat-card {
    background: var(--bg-white);
    border-radius: var(--radius-sm);
    padding: 14px 10px;
    text-align: center;
    box-shadow: var(--shadow);
    transition: all 0.3s;
}

.stat-card:active { transform: scale(0.95); }

.stat-card .stat-emoji { font-size: 28px; margin-bottom: 4px; }
.stat-card .stat-num { font-size: 22px; font-weight: 700; color: var(--text-primary); }
.stat-card .stat-desc { font-size: 11px; color: var(--text-secondary); margin-top: 2px; }

.stat-card.uk { border-top: 3px solid #3B82F6; }
.stat-card.hk { border-top: 3px solid var(--success); }
.stat-card.jp { border-top: 3px solid var(--warning); }

/* ==================== 学校目录 ==================== */
.country-tabs {
    display: flex;
    gap: 8px;
    margin-bottom: 16px;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
    padding: 2px 0;
}

.country-tabs::-webkit-scrollbar { display: none; }

.country-tab {
    padding: 8px 18px;
    border-radius: 24px;
    border: 1.5px solid var(--border);
    background: var(--bg-white);
    font-size: 13px;
    font-weight: 600;
    color: var(--text-secondary);
    cursor: pointer;
    white-space: nowrap;
    transition: all 0.3s;
    flex-shrink: 0;
}

.country-tab.active {
    background: var(--gradient-1);
    color: white;
    border-color: transparent;
    box-shadow: 0 4px 12px rgba(139,92,246,0.3);
}

.country-tab:active { transform: scale(0.95); }

/* 学校卡片 */
.school-card {
    background: var(--bg-white);
    border-radius: var(--radius);
    padding: 16px;
    margin-bottom: 12px;
    box-shadow: var(--shadow);
    position: relative;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    border: 1px solid transparent;
    animation: slideUp 0.4s ease forwards;
    opacity: 0;
}

.school-card:active { transform: scale(0.97); }

.school-card .rank-badge {
    position: absolute;
    top: -1px;
    right: 16px;
    background: var(--gradient-1);
    color: white;
    padding: 4px 12px;
    border-radius: 0 0 10px 10px;
    font-size: 12px;
    font-weight: 700;
}

.school-card .local-badge {
    position: absolute;
    top: 8px;
    right: 8px;
    background: #D1FAE5;
    color: #065F46;
    font-size: 10px;
    padding: 2px 8px;
    border-radius: 12px;
    font-weight: 600;
    z-index: 2;
}

.school-card .school-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
}

.school-logo {
    width: 44px;
    height: 44px;
    border-radius: var(--radius-xs);
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 16px;
    font-weight: 700;
    flex-shrink: 0;
}

.school-name {
    font-size: 15px;
    font-weight: 700;
    color: var(--text-primary);
    line-height: 1.3;
}

.school-name-zh {
    font-size: 12px;
    color: var(--text-secondary);
    font-weight: 500;
}

.school-requirements {
    display: flex;
    gap: 8px;
    margin-bottom: 10px;
}

.req-chip {
    font-size: 11px;
    padding: 3px 10px;
    border-radius: 12px;
    background: #F3F4F6;
    color: var(--text-secondary);
    font-weight: 500;
}

