            <div class="filter-chips" id="filterChips">
                <div class="filter-chip active" data-filter="all" onclick="switchFilter('all')">全部专业</div>
                <div class="filter-chip" data-filter="math" onclick="switchFilter('math')">∑ 数学</div>
                <div class="filter-chip" data-filter="datascience" onclick="switchFilter('datascience')">📊 数据科学</div>
                <div class="filter-chip" data-filter="chemistry" onclick="switchFilter('chemistry')">⚗️ 化学</div>
                <div class="filter-chip" data-filter="crossover" onclick="switchFilter('crossover')">🎨 交叉设计</div>
            </div>

            <!-- 学校列表 -->
            <div id="schoolList"></div>
            <div class="empty-state" id="schoolEmpty" style="display:none;">
                <div class="empty-icon">🔍</div>
                <div class="empty-text">没有找到匹配的院校</div>
            </div>
        </div>

        <!-- ==================== 结论分析页 ==================== -->
        <div class="page" id="page-conclusion">
            <!-- 核心结论 -->
            <div class="conclusion-hero">
                <h2>🌟 核心推荐策略</h2>
                <p>Elysia拥有独特的"<strong>数学×艺术×商业</strong>"复合背景，建议以<strong>香港本地生身份申请港三大</strong>为最佳性价比选择，搭配<strong>英国G5/王爱曼华</strong>冲刺和<strong>日本SGU</strong>保底，形成三地梯度申请策略。<br><br>🔑 <strong>IELTS提分是第一优先级</strong>——当前5.5分距离最低门槛6.0仍需努力。</p>
            </div>

            <!-- IELTS 差距分析 -->
            <div class="card" id="ieltsAnalysis"></div>

            <!-- 分层推荐 -->
            <div id="tierAccordions"></div>

            <!-- 核心洞察 -->
            <div style="font-size:15px;font-weight:700;margin:16px 0 10px;">💡 四大核心洞察</div>
            <div id="insightsList"></div>

            <!-- 三地对比表 -->
            <div style="font-size:15px;font-weight:700;margin:16px 0 10px;">📊 三地留学对比</div>
            <div style="overflow-x:auto;">
                <table class="comparison-table" id="comparisonTable"></table>
            </div>
        </div>

        <!-- ==================== 行动规划时间线 ==================== -->
        <div class="page" id="page-timeline">
            <div class="card card-danger" style="margin-bottom:16px;">
                <div style="font-size:14px;font-weight:700;color:var(--danger);margin-bottom:6px;">
                    🚨 当前最紧急
                </div>
                <div style="font-size:12px;color:var(--text-secondary);line-height:1.7;">
                    <strong>IELTS 备考（8月-12月）</strong>：每天2小时精听+1篇阅读，每周2篇写作批改。<br>
                    <strong>A-Level 选课确认（9月）</strong>：数学(必选)+高数(推荐)+物理/化学+艺术与设计。<br>
                    <strong>12月IELTS考试报名</strong>：目标冲6.0，为2027年3月冲6.5+打基础。
                </div>
            </div>

            <div class="timeline" id="timelineContainer"></div>
        </div>

        <!-- ==================== 专业详情页 ==================== -->
        <div class="page" id="page-program">
            <div class="breadcrumb" id="programBreadcrumb"></div>
            <div id="programDetail"></div>
            <div class="related-programs">
                <h4 style="font-size:14px;font-weight:700;margin-bottom:10px;">🔗 相似专业推荐</h4>
                <div class="related-scroll" id="relatedPrograms"></div>
            </div>
        </div>

        <!-- ==================== 底部导航栏 ==================== -->
        <nav class="bottom-nav" id="bottomNav">
            <div class="nav-item active" data-page="home" onclick="navigateTo('home')">
                <span class="nav-icon">🏠</span>
                <span class="nav-label">首页</span>
            </div>
            <div class="nav-item" data-page="schools" onclick="navigateTo('schools/uk')">
                <span class="nav-icon">🏫</span>
                <span class="nav-label">院校</span>
            </div>
            <div class="nav-item" data-page="conclusion" onclick="navigateTo('conclusion')">
                <span class="nav-icon">📋</span>
                <span class="nav-label">结论</span>
            </div>
            <div class="nav-item" data-page="timeline" onclick="navigateTo('timeline')">
                <span class="nav-icon">📅</span>
                <span class="nav-label">规划</span>
            </div>
        </nav>

        <!-- 返回顶部 -->
        <button class="btn-back-top" id="btnBackTop" onclick="scrollToTop()">↑</button>

        <!-- Toast -->
        <div class="toast" id="toast"></div>
    </div>

    <script src="data.js"></script>
    <script>
    // ==================== 全局状态 ====================
    const state = {
        currentPage: 'home',
        currentCountry: 'uk',
        currentFilter: 'all',
        currentProgram: null,
        openSheet: null,
        searchQuery: '',
        timelineChecks: JSON.parse(localStorage.getItem('elysia_timeline_checks') || '{}'),
        scrollPositions: {}
    };

    // ==================== 路由系统 ====================
    function navigateTo(route, filter) {
        const parts = route.split('/');

        if (parts[0] === 'schools') {
            state.currentPage = 'schools';
            if (parts[1] && ['uk','hk','jp'].includes(parts[1])) {
                state.currentCountry = parts[1];
            }
            if (filter) state.currentFilter = filter;
            showPage('page-schools');
            updateSchoolUI();
            renderSchoolList();
        } else if (route === 'program') {
            // handled by showProgramDetail
        } else {
            state.currentPage = route;
            const pageMap = {
                'home': 'page-home',
                'conclusion': 'page-conclusion',
                'timeline': 'page-timeline'
            };
            const pageId = pageMap[route];
            if (pageId) {
                showPage(pageId);
                if (route === 'conclusion') renderConclusion();
                if (route === 'timeline') renderTimeline();
            }
        }

        updateNavHighlight();
        scrollToTop();
    }

    function showPage(pageId) {
        document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
        const page = document.getElementById(pageId);
        if (page) page.classList.add('active');
    }

    function updateNavHighlight() {
        const navItems = document.querySelectorAll('.nav-item');
        navItems.forEach(item => {
            const p = item.dataset.page;
            if (state.currentPage === 'schools' && p === 'schools') {
                item.classList.add('active');
            } else if (state.currentPage === p) {
                item.classList.add('active');
            } else {
                item.classList.remove('active');
            }
        });

        // Update header title
        const titles = {
            'home': '🎓 Elysia 升学攻略',
            'schools': '🏫 学校专业目录',
            'conclusion': '📋 结论分析',
            'timeline': '📅 行动规划',
            'program': '📖 专业详情'
        };
        document.getElementById('headerTitle').textContent = titles[state.currentPage] || '🎓 Elysia 升学攻略';
    }

    // ==================== 学校目录 ====================
    function switchCountry(country) {
        state.currentCountry = country;
        state.openSheet = null;
        document.querySelectorAll('.country-tab').forEach(t => {
            t.classList.toggle('active', t.dataset.country === country);
        });
        renderSchoolList();
    }

    function switchFilter(filter) {
        state.currentFilter = filter;
        state.openSheet = null;
        document.querySelectorAll('.filter-chip').forEach(c => {
            c.classList.toggle('active', c.dataset.filter === filter);
        });
        renderSchoolList();
    }

    function updateSchoolUI() {
        // Sync country tabs
        document.querySelectorAll('.country-tab').forEach(t => {
            t.classList.toggle('active', t.dataset.country === state.currentCountry);
        });
        // Sync filter chips
        document.querySelectorAll('.filter-chip').forEach(c => {
            c.classList.toggle('active', c.dataset.filter === state.currentFilter);
        });
    }

    function getFilteredProgramIds() {
        const universities = UNIVERSITIES[state.currentCountry] || [];
        let allProgIds = [];
        universities.forEach(u => {
            if (u.programs) allProgIds.push(...u.programs);
        });

        if (state.currentFilter !== 'all') {
            return allProgIds.filter(pid => {
                const p = PROGRAMS.find(pr => pr.id === pid);
                return p && p.category === state.currentFilter;
            });
        }
        return allProgIds;
    }

    function renderSchoolList() {
        const container = document.getElementById('schoolList');
        const empty = document.getElementById('schoolEmpty');
        const universities = UNIVERSITIES[state.currentCountry] || [];
        const query = (document.getElementById('schoolSearch')?.value || '').toLowerCase();

        let filteredUnis = universities;
        if (query) {
            filteredUnis = universities.filter(u => {
                if (u.name.toLowerCase().includes(query)) return true;
                if (u.nameZh.includes(query)) return true;
                const progs = (u.programs || []).map(pid => {
                    const p = PROGRAMS.find(pr => pr.id === pid);
                    return p ? p.name : '';
                });
                return progs.some(pn => pn.toLowerCase().includes(query));
            });
        }

        if (state.currentFilter !== 'all') {
            filteredUnis = filteredUnis.filter(u => {
                return (u.programs || []).some(pid => {
                    const p = PROGRAMS.find(pr => pr.id === pid);
                    return p && p.category === state.currentFilter;
                });
            });
        }

        if (filteredUnis.length === 0) {
            container.innerHTML = '';
            empty.style.display = 'block';
            return;
        }

        empty.style.display = 'none';

        const countryNames = { uk: '英国', hk: '香港', jp: '日本' };

        container.innerHTML = filteredUnis.map((u, i) => {
            const initials = u.nameZh || u.name.split(' ').map(w => w[0]).join('').slice(0, 3);
            const programs = (u.programs || []).map(pid => PROGRAMS.find(p => p.id === pid)).filter(Boolean);
            const isOpen = state.openSheet === u.id;

            let programsHtml = programs.map(p => `
                <span class="program-tag ${p.category}" onclick="event.stopPropagation();toggleProgramSheet('${u.id}', '${p.id}')">${p.name.split('(')[0].split('（')[0].trim()}</span>
            `).join('');

            if (programs.length === 0) {
                programsHtml = '<span style="font-size:11px;color:var(--text-muted);">暂无推荐专业数据</span>';
            }

            // Determine which sheet to show if open
            let sheetHtml = '';
            if (isOpen && state.currentProgram) {
                const sp = PROGRAMS.find(p => p.id === state.currentProgram);
                if (sp) {
                    const catInfo = PROGRAM_CATEGORIES[sp.category];
                    sheetHtml = `
                    <div class="program-sheet open">
                        <h4>${sp.name}</h4>
                        <div style="display:flex;gap:6px;margin-bottom:6px;">
                            <span class="req-chip alevel">A-Level: ${sp.alevel}</span>
                            <span class="req-chip ielts">IELTS: ${sp.ielts}</span>
                            ${sp.portfolio ? `<span class="req-chip" style="background:#FEF3C7;color:#92400E;">${sp.portfolio}</span>` : ''}
                        </div>
                        <div style="font-size:12px;font-weight:600;color:var(--text-primary);margin-bottom:6px;">
                            📖 核心课程
                        </div>
                        <div class="courses-list">
                            ${(sp.courses || []).map(c => `<span class="course-chip">${c}</span>`).join('')}
                        </div>
                        <div class="career-text">
                            <strong>💼 职业方向：</strong>${(sp.careers || []).join(' · ')}
                        </div>
                        <a href="${sp.url}" target="_blank" rel="noopener" class="btn-outlink" onclick="event.stopPropagation();">🔗 查看官网课程页面</a>
                    </div>`;
                }
            }

            return `
            <div class="school-card" style="animation-delay:${i * 0.05}s;">
                ${u.isLocalBenefit ? '<div class="local-badge">💰 本地生优惠</div>' : ''}
                <div class="rank-badge">QS #${u.rank}</div>
                <div class="school-header">
                    <div class="school-logo" style="background:${u.logoColor};">${initials}</div>
                    <div>
                        <div class="school-name">${u.name}</div>
                        <div class="school-name-zh">${u.nameZh} · ${countryNames[state.currentCountry]}</div>
                    </div>
                </div>
                <div class="school-requirements">
                    <span class="req-chip alevel">A-Level: ${u.alevelRange}</span>
                    <span class="req-chip ielts">IELTS: ${u.ieltsRange}</span>
                </div>
                <div style="font-size:11px;color:var(--text-muted);margin-bottom:8px;">${u.desc}</div>
                <div class="school-programs">${programsHtml}</div>
                ${sheetHtml}
            </div>`;
        }).join('');

        // Re-apply animation
        requestAnimationFrame(() => {
            document.querySelectorAll('.school-card').forEach(c => c.style.opacity = '1');
        });
    }

    function toggleProgramSheet(uniId, progId) {
        if (state.openSheet === uniId && state.currentProgram === progId) {
            state.openSheet = null;
            state.currentProgram = null;
        } else {
            state.openSheet = uniId;
            state.currentProgram = progId;
        }
        renderSchoolList();

        // Scroll to the sheet if opened
        if (state.openSheet) {
            setTimeout(() => {
                const sheet = document.querySelector('.program-sheet.open');
                if (sheet) sheet.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }, 100);
        }
    }

    // ==================== 专业详情页 ====================
    function showProgramDetail(progId) {
        const program = PROGRAMS.find(p => p.id === progId);
        if (!program) return;

        state.currentPage = 'program';
        showPage('page-program');
        updateNavHighlight();

        const uni = findUniversityByProgram(progId);
        const countryNames = { UK: '英国', HK: '香港', JP: '日本' };
        const catInfo = PROGRAM_CATEGORIES[program.category];

        document.getElementById('programBreadcrumb').innerHTML = `
            <a href="#" onclick="navigateTo('schools/${(uni?.country||'uk').toLowerCase()}');return false;">${countryNames[uni?.country] || ''}</a>
            <span class="separator">›</span>
            <a href="#" onclick="navigateTo('schools/${(uni?.country||'uk').toLowerCase()}');return false;">${uni?.nameZh || uni?.name || ''}</a>
            <span class="separator">›</span>
            <span>${program.name}</span>
        `;

        document.getElementById('programDetail').innerHTML = `
            <div class="program-detail-card">
                <div class="pd-name">${program.name}</div>
                <span class="pd-category" style="background:${catInfo.color}15;color:${catInfo.color};border:1px solid ${catInfo.color}40;">
                    ${catInfo.icon} ${catInfo.name}
                </span>

                <div class="pd-section">
                    <h4>📋 入学要求</h4>
                    <div style="display:flex;gap:8px;flex-wrap:wrap;">
                        <span class="req-chip alevel" style="font-size:12px;">A-Level: ${program.alevel}</span>
                        <span class="req-chip ielts" style="font-size:12px;">IELTS: ${program.ielts}</span>
                        ${program.portfolio ? `<span class="req-chip" style="background:#FEF3C7;color:#92400E;font-size:12px;">📁 ${program.portfolio}</span>` : ''}
                        ${program.note ? `<span class="req-chip" style="background:#DBEAFE;color:#1D4ED8;font-size:12px;">ℹ️ ${program.note}</span>` : ''}
                        ${program.localFee ? `<span class="req-chip" style="background:#D1FAE5;color:#065F46;font-size:12px;">💰 本地生: ${program.localFee}</span>` : ''}
                    </div>
                </div>

                <div class="section-divider"></div>

                <div class="pd-section">
                    <h4>📖 核心课程</h4>
                    <div class="courses-list">
                        ${(program.courses || []).map(c => `<span class="course-chip">${c}</span>`).join('')}
                    </div>
                </div>

                <div class="section-divider"></div>

                <div class="pd-section">
                    <h4>💼 职业前景</h4>
                    <div class="career-text">${(program.careers || []).join(' · ')}</div>
                </div>

                <a href="${program.url}" target="_blank" rel="noopener" class="pd-link-btn">
                    🔗 查看官网课程页面
                </a>
            </div>
        `;

        // Related programs (same category, different university)
        const related = PROGRAMS.filter(p => p.category === program.category && p.id !== progId).slice(0, 6);
        document.getElementById('relatedPrograms').innerHTML = related.map(r => {
            const ru = findUniversityByProgram(r.id);
            return `
            <div class="related-card" onclick="showProgramDetail('${r.id}')">
                <div class="rel-uni">${ru?.nameZh || ru?.name || ''}</div>
                <div class="rel-name">${r.name.split('(')[0].split('（')[0].trim()}</div>
            </div>`;
        }).join('');

        scrollToTop();
    }

    function findUniversityByProgram(progId) {
        for (const country of ['uk','hk','jp']) {
            const unis = UNIVERSITIES[country] || [];
            for (const u of unis) {
                if ((u.programs || []).includes(progId)) return u;
            }
        }
        return null;
    }

    // ==================== 结论页面 ====================
    function renderConclusion() {
        // IELTS 分析
        const ieltsDiv = document.getElementById('ieltsAnalysis');
        ieltsDiv.innerHTML = `
            <div style="font-size:14px;font-weight:700;margin-bottom:10px;">🎯 IELTS 目标阶梯</div>
            <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
                <span style="font-size:20px;font-weight:700;color:var(--danger);">5.5</span>
                <span>→</span>
                <span style="font-size:16px;font-weight:600;color:#F59E0B;">6.0</span>
                <span>→</span>
                <span style="font-size:16px;font-weight:600;color:#3B82F6;">6.5</span>
                <span>→</span>
                <span style="font-size:16px;font-weight:600;color:#8B5CF6;">7.0</span>
            </div>
            <div style="font-size:12px;color:var(--text-secondary);line-height:1.7;">${CONCLUSIONS.ieltsGap.gap}</div>
        `;

        // 分层推荐
        const tiersDiv = document.getElementById('tierAccordions');
        tiersDiv.innerHTML = ['reach','match','safety'].map(tier => {
            const d = CONCLUSIONS.tiers[tier];
            return `
            <div class="tier-accordion">
                <div class="tier-header" onclick="toggleTier('${tier}')">
                    <h3>
                        <span class="tier-badge ${tier}">${d.title}</span>
                    </h3>
                    <span class="tier-arrow" id="arrow-${tier}">▼</span>
                </div>
                <div class="tier-content open" id="content-${tier}">
                    <div class="tier-desc">${d.desc}</div>
                    ${d.schools.map(s => {
                        const uni = findUniById(s.id);
                        return `
                        <div class="tier-school-item" onclick="navigateTo('schools/${(uni?.country||'uk').toLowerCase()}');return false;" style="cursor:pointer;">
                            <div class="school-dot" style="background:${tier==='reach'?'#EF4444':tier==='match'?'#3B82F6':'#10B981'};"></div>
                            <div class="school-info">
                                <div class="s-name">${uni?.nameZh || ''} · QS #${uni?.rank || '?'}</div>
                                <div class="s-note">${s.note}</div>
                            </div>
                        </div>`;
                    }).join('')}
                </div>
            </div>`;
        }).join('');

        // 洞察
        const insightsDiv = document.getElementById('insightsList');
        insightsDiv.innerHTML = CONCLUSIONS.keyInsights.map(t => `
            <div class="insight-card">${t}</div>
        `).join('');

        // 对比表
        const tableDiv = document.getElementById('comparisonTable');
        const ct = CONCLUSIONS.comparisonTable;
        tableDiv.innerHTML = `
            <thead><tr>${ct.headers.map(h => `<th>${h}</th>`).join('')}</tr></thead>
            <tbody>${ct.rows.map(row => `
                <tr>${row.map((cell, i) => `<td${i===0?' style="font-weight:600;color:var(--text-primary);"':''}>${cell}</td>`).join('')}</tr>
            `).join('')}</tbody>
        `;
    }

    function toggleTier(tier) {
        const content = document.getElementById('content-' + tier);
        const arrow = document.getElementById('arrow-' + tier);
        const isOpen = content.classList.contains('open');
        if (isOpen) {
            content.classList.remove('open');
            arrow.classList.remove('open');
        } else {
            content.classList.add('open');
            arrow.classList.add('open');
        }
    }

    function findUniById(id) {
        for (const country of ['uk','hk','jp']) {
            const unis = UNIVERSITIES[country] || [];
            const found = unis.find(u => u.id === id);
            if (found) return { ...found, country: country.toUpperCase() };
        }
        return null;
    }

    // ==================== 时间线页面 ====================
    function renderTimeline() {
        const container = document.getElementById('timelineContainer');
        container.innerHTML = TIMELINE.map((t, i) => `
            <div class="timeline-item" style="animation-delay:${i * 0.06}s;">
                <div class="timeline-dot ${t.priority}"></div>
                <div class="timeline-card">
                    <div class="timeline-date">${t.date}</div>
                    <div class="timeline-title">${t.title}</div>
                    <div class="timeline-desc">${t.desc}</div>
                    ${t.tasks && t.tasks.length > 0 ? `
                    <ul class="timeline-tasks">
                        ${t.tasks.map((task, j) => {
                            const checkKey = `${t.id}_${j}`;
                            const checked = state.timelineChecks[checkKey];
                            return `
                            <li class="timeline-task" onclick="toggleTaskCheck('${checkKey}', this)">
                                <span class="check-box${checked ? ' checked' : ''}">${checked ? '✓' : ''}</span>
                                <span style="${checked ? 'text-decoration:line-through;color:var(--text-muted);' : ''}">${task}</span>
                            </li>`;
                        }).join('')}
                    </ul>` : ''}
                </div>
            </div>
        `).join('');

        // Re-trigger animation
        requestAnimationFrame(() => {
            document.querySelectorAll('.timeline-item').forEach(c => c.style.opacity = '1');
        });
    }

    function toggleTaskCheck(key, el) {
        const box = el.querySelector('.check-box');
        const text = el.querySelector('span:last-child');
        const wasChecked = state.timelineChecks[key];

        if (wasChecked) {
            delete state.timelineChecks[key];
            box.classList.remove('checked');
            box.textContent = '';
            text.style.textDecoration = '';
            text.style.color = '';
        } else {
            state.timelineChecks[key] = true;
            box.classList.add('checked');
            box.textContent = '✓';
            text.style.textDecoration = 'line-through';
            text.style.color = 'var(--text-muted)';
        }

        localStorage.setItem('elysia_timeline_checks', JSON.stringify(state.timelineChecks));
    }

    // ==================== 工具函数 ====================
    function scrollToTop() {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function showToast(msg) {
        const toast = document.getElementById('toast');
        toast.textContent = msg;
        toast.classList.add('show');
        setTimeout(() => toast.classList.remove('show'), 2000);
    }

    // ==================== 滚动监听 ====================
    let scrollTimer;
    window.addEventListener('scroll', () => {
        const header = document.getElementById('topHeader');
        const backTop = document.getElementById('btnBackTop');

