    const REMINDER_SETTINGS_KEY = 'elysia_reminder_settings';
    const REMINDER_SENT_KEY = 'elysia_reminder_sent';
    const REMINDER_INTERVAL = 60 * 60 * 1000; // 60分钟

    const reminderStore = {
        settings: JSON.parse(localStorage.getItem(REMINDER_SETTINGS_KEY) || '{"enabled":true}'),
        sent: JSON.parse(localStorage.getItem(REMINDER_SENT_KEY) || '{}')
    };

    function saveReminderSettings() {
        localStorage.setItem(REMINDER_SETTINGS_KEY, JSON.stringify(reminderStore.settings));
    }

    function saveReminderSent() {
        localStorage.setItem(REMINDER_SENT_KEY, JSON.stringify(reminderStore.sent));
    }

    function isNotificationSupported() {
        return typeof Notification !== 'undefined';
    }

    function getReminderPermission() {
        if (!isNotificationSupported()) return 'unsupported';
        return Notification.permission;
    }

    // 日期工具：解析 YYYY-MM-DD 为本地零点 Date
    function parseDate(str) {
        const parts = str.split('-').map(Number);
        return new Date(parts[0], parts[1] - 1, parts[2]);
    }

    function formatDeadline(str) {
        const d = parseDate(str);
        return `${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getDate()).padStart(2, '0')}`;
    }

    function getDaysLeft(str) {
        const now = new Date();
        now.setHours(0, 0, 0, 0);
        const target = parseDate(str);
        return Math.round((target - now) / (1000 * 60 * 60 * 24));
    }

    function getDeadlineBadgeClass(str) {
        const days = getDaysLeft(str);
        if (days < 0) return 'badge-past';
        if (days <= 14) return 'badge-urgent';
        if (days <= 60) return 'badge-soon';
        return 'badge-later';
    }

    // 请求通知权限
    function requestNotificationPermission() {
        if (!isNotificationSupported()) {
            showToast('当前浏览器不支持系统通知');
            return;
        }
        if (Notification.permission === 'granted') {
            showToast('✅ 系统通知已开启');
            return;
        }
        if (Notification.permission === 'denied') {
            showToast('⚠️ 通知权限被拒绝，请到浏览器设置中开启');
            return;
        }
        Notification.requestPermission().then(perm => {
            reminderStore.settings.permission = perm;
            saveReminderSettings();
            updateReminderUI();
            if (perm === 'granted') {
                showToast('✅ 系统通知已开启');
            }
        });
    }

    // 切换提醒总开关
    function toggleReminderMaster(checked) {
        reminderStore.settings.enabled = checked;
        saveReminderSettings();
        updateReminderUI();
        showToast(checked ? '🔔 提醒已开启' : '🔕 提醒已关闭');
    }

    // 发送提醒（通知或 Toast 降级）
    function fireReminder(item, daysLeft) {
        const title = `⏰ ${item.title.replace(/&#\d+;/g, '').replace(/⚡|🔥/g, '')}`;
        const body = `截止日期 ${formatDeadline(item.deadline)}（${item.date}），剩余 ${daysLeft} 天`;

        if (isNotificationSupported() && Notification.permission === 'granted') {
            try {
                new Notification(title, {
                    body,
                    icon: 'qrcode.png',
                    badge: 'qrcode.png',
                    tag: `reminder-${item.id}`,
                    renotify: true,
                    data: { url: './index.html#timeline', timelineId: item.id }
                });
            } catch (e) {
                showToast(`${title}：${body}`);
