            if (upcoming.length > 0) {
                badge.style.display = '';
                badge.textContent = upcoming.length;
                badge.className = 'reminder-badge' + (urgent.length > 0 ? ' reminder-badge-urgent' : '');
                const next = upcoming[0];
                status.innerHTML = `最近截止：<strong>${next.item.title.replace(/&#\d+;/g, '')}</strong>（${next.daysLeft}天后）`;
            } else {
                badge.style.display = 'none';
                status.textContent = reminderStore.settings.enabled ? '近期暂无临近截止节点' : '提醒已关闭，点击开启';
            }
        }

        // 时间线面板
        const switchEl = document.getElementById('reminderMasterSwitch');
        const permRow = document.getElementById('reminderPermissionRow');
        const listEl = document.getElementById('upcomingReminders');
        if (!switchEl || !permRow || !listEl) return;

        switchEl.checked = !!reminderStore.settings.enabled;

        const perm = getReminderPermission();
        if (perm === 'granted') {
            permRow.innerHTML = `<div class="reminder-perm-status perm-granted">✅ 系统通知已授权 · 截止日前自动提醒</div>`;
        } else if (perm === 'denied') {
            permRow.innerHTML = `<div class="reminder-perm-status perm-denied">⚠️ 通知权限被拒绝，请在浏览器设置中重新开启</div>`;
        } else if (perm === 'unsupported') {
            permRow.innerHTML = `<div class="reminder-perm-status perm-warn">📱 当前浏览器不支持系统通知，将使用页面内提醒</div>`;
        } else {
            permRow.innerHTML = `<div class="reminder-perm-status perm-default">
                <span>🔕 尚未授权系统通知</span>
                <button class="reminder-perm-btn" onclick="requestNotificationPermission()">开启通知</button>
            </div>`;
        }

        // 即将到来列表
        const upcoming = getUpcomingReminders(180);
        if (upcoming.length === 0) {
            listEl.innerHTML = `<div class="reminder-empty">暂无未来 6 个月的截止节点</div>`;
        } else {
            listEl.innerHTML = upcoming.map(x => {
                const inWindow = x.daysLeft <= x.item.reminderDays;
                return `
                <div class="reminder-item${inWindow ? ' active' : ''}">
                    <div class="reminder-item-info">
                        <div class="reminder-item-title">${x.item.title.replace(/&#\d+;/g, '')}</div>
