                    </div>
                    <span class="reminder-item-days ${x.daysLeft < 0 ? 'past' : (inWindow ? 'urgent' : '')}">
                        ${x.daysLeft < 0 ? '已截止' : (inWindow ? '⚠ ' + x.daysLeft + '天' : x.daysLeft + '天后')}
                    </span>
                </div>`;
            }).join('');
        }
    }

    function getUpcomingReminders(maxDays) {
        const list = [];
        TIMELINE.forEach(item => {
            if (!item.deadline) return;
            const daysLeft = getDaysLeft(item.deadline);
            if (daysLeft < -30) return; // 已过期超过30天不显示
            if (daysLeft > maxDays) return;
            list.push({ item, daysLeft });
        });
        list.sort((a, b) => a.daysLeft - b.daysLeft);
        return list;
    }

    // 注册 Service Worker
    function registerServiceWorker() {
        if (!('serviceWorker' in navigator)) return;
        window.addEventListener('load', () => {
            navigator.serviceWorker.register('./sw.js')
                .then(reg => console.log('[Reminder] SW registered:', reg.scope))
                .catch(err => console.log('[Reminder] SW register failed:', err));
        });
    }

    // 启动提醒引擎
    function initReminderEngine() {
        registerServiceWorker();
        // 首次立即检查
        checkReminders(true);
        // 每60分钟轮询
        setInterval(() => checkReminders(false), REMINDER_INTERVAL);
        // 回到前台时也检查一次
        document.addEventListener('visibilitychange', () => {
            if (!document.hidden) checkReminders(false);
        });
    }
