const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType, ShadingType
} = require("docx");

const border = { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };
const cellMargins = { top: 60, bottom: 60, left: 100, right: 100 };
const headerBlue = "2E75B6";
const headerShading = { fill: "2E75B6", type: ShadingType.CLEAR };
const altShading = { fill: "F2F7FB", type: ShadingType.CLEAR };
const warnShading = { fill: "FFF3CD", type: ShadingType.CLEAR };
const greenShading = { fill: "E9F5E9", type: ShadingType.CLEAR };

function h1(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(text)] });
}
function h2(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(text)] });
}
function para(text, opts = {}) {
  return new Paragraph({ spacing: { after: 120, line: 276 }, children: [new TextRun({ text, ...opts })] });
}
function bullet(text, opts = {}) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { after: 60, line: 276 },
    children: [new TextRun({ text, ...opts })]
  });
}
function headerCell(text, width) {
  return new TableCell({
    borders, width: { size: width, type: WidthType.DXA }, shading: headerShading, margins: cellMargins,
    verticalAlign: "center",
    children: [new Paragraph({ children: [new TextRun({ text, bold: true, color: "FFFFFF", size: 18 })] })]
  });
}
function cell(text, width, shading = null) {
  let children;
  if (typeof text === "string") children = [new Paragraph({ margins: cellMargins, children: [new TextRun({ text, size: 18 })] })];
  else children = text.map(t => new Paragraph({ margins: cellMargins, children: [new TextRun({ text: t, size: 18 })] }));
  return new TableCell({ borders, width: { size: width, type: WidthType.DXA }, shading, margins: cellMargins, children });
}
function table(headers, widths, rows, rowShading = null) {
  const headerRow = new TableRow({ tableHeader: true, children: headers.map((h, i) => headerCell(h, widths[i])) });
  const dataRows = rows.map((r, i) => new TableRow({
    children: r.map((c, j) => {
      let sh = i % 2 === 0 ? altShading : null;
      if (rowShading && rowShading[i]) sh = rowShading[i];
      return cell(c, widths[j], sh);
    })
  }));
  return new Table({
    width: { size: widths.reduce((a, b) => a + b, 0), type: WidthType.DXA },
    columnWidths: widths,
    rows: [headerRow, ...dataRows],
  });
}
function divider() {
  return new Paragraph({ spacing: { before: 200, after: 200 }, children: [] });
}
function note(text) {
  return new Paragraph({
    spacing: { before: 80, after: 120, line: 276 },
    children: [new TextRun({ text, size: 18, color: "777777", italics: true })]
  });
}

