 *   - current（当前）：进行中（date 覆盖今天）或 deadline 距今天 -7~14 天
 *   - oneMonth（一个月内）：deadline 距今天 15~45 天
 *   - threeMonths（三个月内）：deadline 距今天 46~120 天
 * 输出：webapp/reminders.js（页面 <script> 直接引用，KEY_ALERTS 全局常量）
 */
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const ROOT = path.join(__dirname, 'RoboX', 'webapp');
const DATA_FILE = path.join(ROOT, 'data.js');
const OUT_FILE = path.join(ROOT, 'reminders.js');

function pad(n) { return String(n).padStart(2, '0'); }

/** 今天（本地时区）的 YYYY-MM-DD */
function todayStr() {
    const d = new Date();
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

/** YYYY-MM-DD -> Date(本地零时) */
function parseDate(s) {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s || '');
    if (!m) return null;
    return new Date(+m[1], +m[2] - 1, +m[3]);
}

/** deadline 距今天的自然日差（正数=未来） */
function daysUntil(deadline) {
    const d = parseDate(deadline);
    if (!d) return null;
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    return Math.round((d - today) / 86400000);
}

/**
 * 判断 TIMELINE 节点的 date 区间（如 '2026年8月-9月'）是否覆盖今天。
 * 支持 '2026年10月' / '2027年1月-2月' / '2026年8月-9月' 等格式。
 */
function coversToday(dateText) {
    const m = /(\d{4})年(\d{1,2})月(?:-(\d{1,2})月)?/.exec(dateText || '');
    if (!m) return false;
    const now = new Date();
    const y = now.getFullYear();
    const mo = now.getMonth() + 1;
    const y1 = +m[1], m1 = +m[2], m2 = m[3] ? +m[3] : m1;
    return (y === y1) && (mo >= m1 && mo <= m2);
}

/** 日期字符串 +N 天 -> YYYY-MM-DD */
function plusDays(s, n) {
    const d = parseDate(s);
    d.setDate(d.getDate() + n);
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

function main() {
    const src = fs.readFileSync(DATA_FILE, 'utf8');
    // data.js 为纯数据（无 DOM 引用），在沙箱中执行提取 TIMELINE
    const sandbox = {};
    vm.createContext(sandbox);
    vm.runInContext(src + '\n;globalThis.__out = { TIMELINE, ELYSIA_PROFILE };', sandbox);
    const TIMELINE = sandbox.__out.TIMELINE;
    if (!Array.isArray(TIMELINE) || TIMELINE.length === 0) {
        console.error('ERROR: 未能从 data.js 解析 TIMELINE');
        process.exit(1);
    }

    const today = todayStr();
    const buckets = { current: [], oneMonth: [], threeMonths: [] };
    const priorityRank = { urgent: 0, high: 1, medium: 2, low: 3 };

    for (const t of TIMELINE) {
        const dl = parseDate(t.deadline);
        if (!dl) continue;
        const d = daysUntil(t.deadline);
        const item = {
            id: t.id,
            date: t.date,
            title: t.title.replace(/&#9889;?/g, '').trim(),
            deadline: t.deadline,
            daysLeft: d,
            priority: t.priority || 'medium',
            desc: (t.desc || '').slice(0, 90) + ((t.desc || '').length > 90 ? '…' : '')
        };
        let bucket = null;
        if (coversToday(t.date)) {
