        } else if (d >= 15 && d <= 45) {
            bucket = 'oneMonth';
        } else if (d >= 46 && d <= 120) {
            bucket = 'threeMonths';
        }
        if (bucket) buckets[bucket].push(item);
    }

    // 每档：按紧急度排序（priority 权重 + 天数近优先），取前 4 条
    for (const k of Object.keys(buckets)) {
        buckets[k].sort((a, b) => {
            const pa = priorityRank[a.priority] ?? 3, pb = priorityRank[b.priority] ?? 3;
            if (pa !== pb) return pa - pb;
            return a.daysLeft - b.daysLeft;
        });
