 * 生成时间：${today}　由 codebuddy/gen_reminders.js 生成
 * 档位：当前（进行中/临期7天）、一个月内（15-45天）、三个月内（46-120天）
 */
const KEY_ALERTS = {
    generatedAt: '${today}',
    nextUpdate: '${plusDays(today, 3)}',
    buckets: ${JSON.stringify(buckets, null, 4)}
};
`;

    fs.writeFileSync(OUT_FILE, out, 'utf8');
    const count = Object.values(buckets).reduce((s, a) => s + a.length, 0);
    console.log(`OK: ${OUT_FILE}`);
    console.log(`生成时间：${today}，三档共 ${count} 条`);
    for (const k of Object.keys(buckets)) {
        console.log(`  [${k}] ${buckets[k].map(i => `${i.date} ${i.title}`).join(' / ') || '（空）'}`);
    }
}

main();
