// index.js
const WEB_URL = process.env.WEB_URL || 'https://ai-native-d8gox2tz63118e2f3-1334209523.tcloudbaseapp.com/';
const REMINDERS_URL = WEB_URL + 'reminders.js';
const TOKEN_ELYSIA = process.env.PUSHPLUS_TOKEN_ELYSIA || '';
const TOKEN_ANSON = process.env.PUSHPLUS_TOKEN_ANSON || '';

const BUCKET_META = [
  { key: 'current', icon: '🔴', label: '当前重点' },
  { key: 'oneMonth', icon: '🟠', label: '一个月内' },
  { key: 'threeMonths', icon: '🟡', label: '三个月内' },
];

async function fetchReminders() {
  const res = await fetch(REMINDERS_URL);
  if (!res.ok) throw new Error('拉取 reminders.js 失败: HTTP ' + res.status);
  const text = await res.text();
  const m = /const\s+KEY_ALERTS\s*=\s*(\{[\s\S]*?\});/.exec(text);
  if (!m) throw new Error('解析 reminders.js 失败');
  const data = JSON.parse(m[1]);
  return data;
}

function buildMessage(alerts) {
  const lines = ['📢 Elysia 升学重点任务提醒', ''];
  for (const b of BUCKET_META) {
    const items = (alerts.buckets && alerts.buckets[b.key]) || [];
    lines.push(`${b.icon} ${b.label}`);
    if (!items.length) { lines.push('　暂无临近事项，保持节奏'); lines.push(''); continue; }
    items.forEach(it => {
      const d = it.daysLeft;
      const dTxt = d < 0 ? '已到/过期' : d === 0 ? '今天到期' : `${d}天后`;
      const p = it.priority === 'urgent' ? '🔥' : it.priority === 'high' ? '⭐' : '';
      lines.push(`　${p}${it.title}（${it.date}）· ${dTxt}`);
    });
    lines.push('');
  }
  lines.push(`📅 更新于 ${alerts.generatedAt} · 数据与网页同步`);
  lines.push(`🔗 ${WEB_URL}`);
  return lines.join('\n');
}

async function sendWechat(token, title, content) {
  if (!token) return { skipped: true };
  const res = await fetch('http://www.pushplus.plus/send', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ token, title, content, template: 'txt' }),
  });
  const json = await res.json();
  return json;
}

exports.main = async (event) => {
  try {
    const alerts = await fetchReminders();
    const content = buildMessage(alerts);
    const title = `📢 Elysia 重点任务提醒（${alerts.generatedAt}）`;
    const results = {};
    results.elysia = await sendWechat(TOKEN_ELYSIA, title, content);
    results.anson = await sendWechat(TOKEN_ANSON, title, content);
    const skipped = [results.elysia, results.anson].every(r => r && r.skipped);
    if (skipped) {
      return { code: 0, msg: '未配置 PushPlus token，已跳过推送（请在环境变量配置 PUSHPLUS_TOKEN_ELYSIA / PUSHPLUS_TOKEN_ANSON）' };
    }
    return { code: 0, msg: '推送完成', results };
  } catch (e) {
    console.error(e);
    return { code: 1, msg: '推送失败: ' + e.message };
  }
};
```

